// Packages: AWSSDK.S3, Amazon.S3
using Amazon.S3;
using Amazon.S3.Model;

public static string GenerateUploadPresignedUrl(string key, TimeSpan? expiresIn = null)
{
    try
    {
        var s3Client = new AmazonS3Client(RegionEndpoint.USEast1);

        var request = new GetPreSignedUrlRequest
        {
            BucketName = "aspnet-aws-demo-bucket",
            Key = key,
            Verb = HttpVerb.PUT,
            Expires = DateTime.UtcNow.Add(expiresIn ?? TimeSpan.FromMinutes(15)),
            ContentType = "image/jpeg"
        };

        string uploadUrl = s3Client.GetPreSignedURL(request);
        Console.WriteLine($"Upload URL: {uploadUrl}");
        return uploadUrl;
    }
    catch (AmazonS3Exception ex)
    {
        Console.WriteLine($"Error generating upload URL: {ex.Message}");
        throw;
    }
}

// Usage:
// string url = GenerateUploadPresignedUrl("uploads/user-123/photo.jpg", TimeSpan.FromMinutes(10));
