// Packages: AWSSDK.S3, Amazon.S3
using System.Net.Http.Headers;

public static async Task UploadToPresignedUrlAsync(string presignedUrl, string filePath, string contentType)
{
    try
    {
        using var httpClient = new HttpClient();
        using var fileStream = File.OpenRead(filePath);
        using var content = new StreamContent(fileStream)
        {
            Headers = { ContentType = new MediaTypeHeaderValue(contentType) }
        };

        HttpResponseMessage response = await httpClient.PutAsync(presignedUrl, content);
        Console.WriteLine($"Status: {response.StatusCode}");

        if (!response.IsSuccessStatusCode)
        {
            string errorBody = await response.Content.ReadAsStringAsync();
            Console.WriteLine($"Error body: {errorBody}");
            response.EnsureSuccessStatusCode();
        }
    }
    catch (HttpRequestException ex)
    {
        Console.WriteLine($"HTTP upload error: {ex.Message}");
        throw;
    }
}

// Usage:
// await UploadToPresignedUrlAsync(uploadUrl, "photo.jpg", "image/jpeg");
// Expected output: "Status: 200 OK"
